steps.response_text:
{
  "case_id": "C04",
  "audience": "Coaches and sports-science students",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "Why this comes up",
      "narration": "Iron deficiency without anaemia is reported in 15 to 35 per cent of adolescent endurance athletes, depending on the ferritin threshold used.",
      "on_screen": "Title card: iron deficiency without anaemia. Text: reported in 15 to 35 per cent of adolescent endurance athletes; range varies with the ferritin threshold used. Tag: review-level background.",
      "claim_refs": ["CL04"]
    },
    {
      "beat": "What was tested",
      "narration": "This randomised, blinded trial gave 214 athletes aged 15-18 with serum ferritin below 30 micrograms per litre 60 mg elemental iron on alternate days for 12 weeks, or placebo.",
      "on_screen": "Trial card: 214 athletes randomised; age 15-18 years; enrolment ferritin below 30 micrograms per litre; 60 mg elemental iron, alternate days, 12 weeks; blinded allocation, block randomisation stratified by sex and site; single central laboratory, baseline and week 12.",
      "claim_refs": ["CL01", "CL08"]
    },
    {
      "beat": "Why alternate days (analogy)",
      "narration": "Background: daily oral iron raises hepcidin for 24 hours or more, blunting the next dose, like a gate that stays shut. Alternate-day dosing was proposed on that rationale; hepcidin was not measured here.",
      "on_screen": "Simple gate animation. Caption: hepcidin raised for 24 hours or more after daily oral iron (background). Caption: alternate-day dosing proposed on this rationale; evidence in adolescents is limited; hepcidin not measured in this trial; no daily-dosing comparator arm.",
      "claim_refs": ["CL05", "CL06"]
    },
    {
      "beat": "Ferritin result",
      "narration": "Ferritin rose 18.4 micrograms per litre with iron, versus 2.1 with placebo: a difference of 16.3, 95% CI 12.9 to 19.7, p less than 0.001.",
      "on_screen": "Two bars. Iron arm +18.4 micrograms per litre; placebo arm +2.1 micrograms per litre. Between-group difference 16.3 micrograms per litre, 95% CI 12.9 to 19.7, p < 0.001. Adherence by pill count 91%.",
      "claim_refs": ["CL01", "CL07"]
    },
    {
      "beat": "Haemoglobin",
      "narration": "Haemoglobin differed by 1.5 grams per litre, 95% CI 0.2 to 2.8; the record calls this change small.",
      "on_screen": "Haemoglobin: iron arm 1.9 grams per litre, placebo arm 0.4 grams per litre, between-group difference 1.5 grams per litre, 95% CI 0.2 to 2.8; no p-value reported. Caption: described as small, as expected in a non-anaemic population.",
      "claim_refs": ["CL02"]
    },
    {
      "beat": "Tolerability",
      "narration": "Gastrointestinal events: 21 of 107 on iron, 9 of 107 on placebo, with no statistical test reported.",
      "on_screen": "Counts side by side: gastrointestinal adverse events 21 of 107 participants (iron), 9 of 107 participants (placebo). Caption: adverse events solicited at each visit; no test, interval or p-value reported for this comparison.",
      "claim_refs": ["CL03"]
    },
    {
      "beat": "What it does not show",
      "narration": "No performance endpoint was measured, and there was no daily-dosing comparator; this applies only to athletes below that enrolment threshold.",
      "on_screen": "Limitations card: no performance endpoint measured; no daily-dosing comparator arm; hepcidin not measured; result applies to athletes aged 15-18 with serum ferritin below 30 micrograms per litre; assays at baseline and week 12 only. A trial result, not dosing advice.",
      "claim_refs": ["CL01", "CL06", "CL08"]
    }
  ]
}
